content.content:
1	"use client";
2	
3	/**
4	 * FLAGSHIP — "Combined" greatest-hits game-server landing template.
5	 *
6	 * Curated merge of the three approved preview directions, composed into one
7	 * coherent premium page (NOT a stack of all three):
8	 *
9	 *   • from CINEMATIC — the full-bleed key-art hero with a navy-scrimmed
10	 *     asymmetric split + a genuinely-animated LIVE server panel (ticking player
11	 *     count, a drawn TPS graph, a streaming console) and slow scroll parallax;
12	 *     plus the plan cards and the blurred-art cinematic CTA.
13	 *   • from EDITORIAL — the numbered buying-reasons rail with the scroll-linked
14	 *     progress spine, beside a STICKY recommended plan card whose 47-second
15	 *     deploy ring counts up as it pins.
16	 *   • from COMMAND DECK — a HUD/console deploy beat: a glass terminal that types
17	 *     its boot sequence to "✓ online in 47s" next to animated telemetry gauges.
18	 *
19	 * Reuses the shared kit hooks/atoms + the scoped `pv-*` motion system so it
20	 * stays in the same design language. Everything respects prefers-reduced-motion.
21	 *
22	 * Net-new, PREVIEW-ONLY. Touches no live page or shared component.
23	 */
24	
25	import Link from "next/link";
26	import { useState } from "react";
27	import type { PreviewGame } from "./data";
28	import {
29	  usePrefersReducedMotion,
30	  useInViewOnce,
31	  useJitter,
32	  useCountUp,
33	  useParallax,
34	  useScrollProgress,
35	  useTypedLines,
36	  StarRow,
37	  ReasonIcon,
38	} from "./kit";
39	import { GameLogo } from "@/components/marketing/GameLogo";
40	import {
41	  IconBolt,
42	  IconShield,
43	  IconNvme,
44	  IconGlobe,
45	  IconUsers,
46	  IconClock,
47	  IconCheck,
48	} from "@/components/marketing/icons";
49	
50	/* ── Live TPS sparkline — draws on view, pulsing playhead (from Cinematic) ── */
51	function TpsGraph({ accent, active, reduced }: { accent: string; active: boolean; reduced: boolean }) {
52	  const pts = [19.9, 20, 19.8, 20, 20, 19.7, 20, 19.9, 20, 20, 19.8, 20];
53	  const w = 220;
54	  const h = 46;
55	  const min = 19.5;
56	  const max = 20.2;
57	  const step = w / (pts.length - 1);
58	  const coords = pts.map((v, i) => {
59	    const x = i * step;
60	    const y = h - ((v - min) / (max - min)) * h;
61	    return [x, y] as const;
62	  });
63	  const line = coords.map(([x, y], i) => `${i === 0 ? "M" : "L"}${x.toFixed(1)} ${y.toFixed(1)}`).join(" ");
64	  const area = `${line} L${w} ${h} L0 ${h} Z`;
65	  const [ex, ey] = coords[coords.length - 1];
66	  return (
67	    <svg viewBox={`0 0 ${w} ${h}`} className="h-[46px] w-full" preserveAspectRatio="none" aria-hidden>
68	      <defs>
69	        <linearGradient id="pv-cmb-tps-fill" x1="0" y1="0" x2="0" y2="1">
70	          <stop offset="0%" stopColor={accent} stopOpacity="0.35" />
71	          <stop offset="100%" stopColor={accent} stopOpacity="0" />
72	        </linearGradient>
73	      </defs>
74	      <path d={area} fill="url(#pv-cmb-tps-fill)" />
75	      <path
76	        d={line}
77	        fill="none"
78	        stroke={accent}
79	        strokeWidth="1.6"
80	        strokeLinecap="round"
81	        strokeLinejoin="round"
82	        className={reduced || !active ? "" : "pv-draw"}
83	      />
84	      <circle cx={ex} cy={ey} r="3" fill={accent} className={reduced ? "" : "motion-safe:animate-pulse-dot"} />
85	    </svg>
86	  );
87	}
88	
89	/* ── Floating LIVE control panel — hero right column (from Cinematic) ──────── */
90	function LiveOpsPanel({ game }: { game: PreviewGame }) {
91	  const reduced = usePrefersReducedMotion();
92	  const { ref, seen } = useInViewOnce<HTMLDivElement>();
93	  const totalSlots = 60;
94	  const players = useJitter(47, 3, seen, 2400, reduced);
95	  const filled = Math.min(totalSlots, players);
96	  const cpu = useCountUp(38, seen, 1200, reduced);
97	  const ping = useJitter(12, 2, seen, 3000, reduced);
98	
99	  const logLines = [
100	    { t: "player connected · s.singe", c: "text-emerald-300" },
101	    { t: "player connected · DevReez", c: "text-emerald-300" },
102	    { t: "[Oxide] loaded 14 plugins", c: "text-slate-400" },
103	    { t: "map saved (0.4s) · autobackup ok", c: "text-slate-500" },
104	  ];
105	
106	  return (
107	    <div ref={ref} className={reduced ? "" : "pv-float"}>
108	      <div className="relative overflow-hidden rounded-2xl border border-white/10 bg-[#080d18]/85 shadow-2xl shadow-black/50 backdrop-blur-xl">
109	        <div
110	          className="pointer-events-none absolute -inset-16 -z-10 opacity-70"
111	          style={{ background: `radial-gradient(45% 45% at 80% 0%, ${game.accent}33, transparent 70%)` }}
112	          aria-hidden
113	        />
114	        {/* header */}
115	        <div className="flex items-center gap-2 border-b border-white/[0.06] bg-white/[0.02] px-4 py-2.5">
116	          <GameLogo family={game.family} size={22} />
117	          <span className="ml-0.5 truncate text-[11px] font-medium text-slate-300">{game.worldName}</span>
118	          <span className="ml-auto inline-flex shrink-0 items-center gap-1.5 rounded-full bg-emerald-500/12 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-emerald-300">
119	            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
120	            running
121	          </span>
122	        </div>
123	
124	        <div className="space-y-4 p-4">
125	          {/* live stat row */}
126	          <div className="grid grid-cols-3 gap-2.5">
127	            <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
128	              <p className="text-[10px] uppercase tracking-wide text-slate-500">Players</p>
129	              <p className="mt-0.5 font-mono text-lg font-semibold text-white tabular-nums">
130	                {filled}
131	                <span className="text-sm text-slate-500">/{totalSlots}</span>
132	              </p>
133	            </div>
134	            <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
135	              <p className="text-[10px] uppercase tracking-wide text-slate-500">Ping</p>
136	              <p className="mt-0.5 font-mono text-lg font-semibold text-white tabular-nums">
137	                {ping}
138	                <span className="text-sm text-slate-500"> ms</span>
139	              </p>
140	            </div>
141	            <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
142	              <p className="text-[10px] uppercase tracking-wide text-slate-500">CPU</p>
143	              <p className="mt-0.5 font-mono text-lg font-semibold text-white tabular-nums">
144	                {cpu}
145	                <span className="text-sm text-slate-500">%</span>
146	              </p>
147	            </div>
148	          </div>
149	
150	          {/* TPS graph */}
151	          <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3.5 pb-2 pt-3">
152	            <div className="flex items-center justify-between">
153	              <p className="text-[11px] font-medium text-slate-400">Server TPS · last 60s</p>
154	              <p className="font-mono text-[11px] font-semibold" style={{ color: game.accent }}>
155	                20.0
156	              </p>
157	            </div>
158	            <div className="mt-1">
159	              <TpsGraph accent={game.accent} active={seen} reduced={reduced} />
160	            </div>
161	          </div>
162	
163	          {/* player slots */}
164	          <div>
165	            <div className="mb-2 flex items-center justify-between text-[11px]">
166	              <span className="text-slate-400">Player slots</span>
167	              <span className="font-mono text-slate-500">{filled} online</span>
168	            </div>
169	            <div className="grid grid-cols-12 gap-1">
170	              {Array.from({ length: totalSlots }).map((_, i) => (
171	                <span
172	                  key={i}
173	                  className={`h-2.5 origin-bottom rounded-[3px] ${reduced ? "" : "motion-safe:animate-grow-up"} ${
174	                    i < filled ? "" : "border border-white/10 bg-white/[0.03]"
175	                  }`}
176	                  style={
177	                    i < filled
178	                      ? { background: `linear-gradient(to top, ${game.accent}, #3b82f6)`, animationDelay: `${i * 14}ms` }
179	                      : undefined
180	                  }
181	                />
182	              ))}
183	            </div>
184	          </div>
185	
186	          {/* streaming console */}
187	          <div className="rounded-xl border border-white/[0.06] bg-black/40 p-3 font-mono text-[11px] leading-relaxed">
188	            {logLines.map((l, i) => (
189	              <div
190	                key={i}
191	                className={`${l.c} ${reduced ? "" : "motion-safe:animate-line-in"}`}
192	                style={{ animationDelay: `${300 + i * 260}ms` }}
193	              >
194	                {l.t}
195	              </div>
196	            ))}
197	            <div className="mt-0.5 flex items-center text-slate-500">
198	              <span className="text-emerald-400">&gt;&nbsp;</span>
199	              <span className="inline-block h-3 w-1.5 bg-slate-400 motion-safe:animate-blink" />
200	            </div>
201	          </div>
202	        </div>
203	      </div>
204	    </div>
205	  );
206	}
207	
208	/* ── 47-second deploy ring — counts up + fills on view (from Editorial) ───── */
209	function DeployRing({ accent }: { accent: string }) {
210	  const reduced = usePrefersReducedMotion();
211	  const { ref, seen } = useInViewOnce<HTMLDivElement>();
212	  const val = useCountUp(47, seen, 1300, reduced);
213	  const r = 34;
214	  const c = 2 * Math.PI * r;
215	  const offset = c * (1 - Math.min(1, val / 47));
216	  return (
217	    <div ref={ref} className="flex items-center gap-4">
218	      <div className="relative h-[92px] w-[92px] shrink-0">
219	        <svg viewBox="0 0 92 92" className="h-full w-full -rotate-90">
220	          <circle cx="46" cy="46" r={r} fill="none" stroke="rgba(255,255,255,0.08)" strokeWidth="6" />
221	          <circle
222	            cx="46"
223	            cy="46"
224	            r={r}
225	            fill="none"
226	            stroke={accent}
227	            strokeWidth="6"
228	            strokeLinecap="round"
229	            strokeDasharray={c}
230	            strokeDashoffset={offset}
231	          />
232	        </svg>
233	        <div className="absolute inset-0 flex flex-col items-center justify-center">
234	          <span className="font-mono text-2xl font-bold tabular-nums text-white">{val}</span>
235	          <span className="text-[10px] font-medium uppercase tracking-wide text-slate-500">sec</span>
236	        </div>
237	      </div>
238	      <div>
239	        <p className="text-sm font-semibold text-white">Live in 47 seconds</p>
240	        <p className="mt-1 text-xs leading-relaxed text-slate-400">
241	          From checkout to a running, connect-ready server — measured, not marketing.
242	        </p>
243	      </div>
244	    </div>
245	  );
246	}
247	
248	/* ── animated telemetry gauge (from Command Deck) ─────────────────────────── */
249	function Gauge({
250	  label,
251	  value,
252	  suffix,
253	  pct,
254	  accent,
255	  active,
256	  reduced,
257	  delay,
258	}: {
259	  label: string;
260	  value: number | string;
261	  suffix?: string;
262	  pct: number;
263	  accent: string;
264	  active: boolean;
265	  reduced: boolean;
266	  delay: number;
267	}) {
268	  return (
269	    <div>
270	      <div className="mb-1.5 flex items-baseline justify-between">
271	        <span className="text-[11px] font-medium uppercase tracking-wide text-slate-400">{label}</span>
272	        <span className="font-mono text-sm font-semibold tabular-nums text-white">
273	          {value}
274	          {suffix && <span className="text-slate-500">{suffix}</span>}
275	        </span>
276	      </div>
277	      <div className="h-2 w-full overflow-hidden rounded-full bg-white/[0.06]">
278	        <div
279	          className={`h-full origin-left rounded-full ${reduced || !active ? "" : "motion-safe:animate-grow-x"}`}
280	          style={{
281	            width: `${pct}%`,
282	            background: `linear-gradient(90deg, #3b82f6, ${accent})`,
283	            animationDelay: `${delay}ms`,
284	          }}
285	        />
286	      </div>
287	    </div>
288	  );
289	}
290	
291	/* ── HUD deploy beat — typing terminal + telemetry gauges (from Command Deck) */
292	function DeployBeat({ game }: { game: PreviewGame }) {
293	  const reduced = usePrefersReducedMotion();
294	  const { ref, seen } = useInViewOnce<HTMLDivElement>();
295	  const players = useJitter(47, 3, seen, 2500, reduced);
296	  const cpu = useJitter(38, 4, seen, 2200, reduced);
297	  const ram = useJitter(61, 3, seen, 2800, reduced);
298	  const { done, current, caret } = useTypedLines(game.boot, seen, reduced);
299	  const totalSlots = 60;
300	
301	  return (
302	    <div ref={ref} className={reduced ? "" : "pv-float-slow"}>
303	      <div
304	        className="relative overflow-hidden rounded-3xl border border-white/10 bg-[#070c17]/90 backdrop-blur-xl"
305	        style={{ boxShadow: `0 40px 120px -50px ${game.accent}80, 0 0 0 1px rgba(255,255,255,0.04)` }}
306	      >
307	        {/* drifting grid backdrop */}
308	        <div
309	          className={`pointer-events-none absolute inset-0 opacity-[0.5] ${reduced ? "" : "pv-grid-pan"}`}
310	          style={{
311	            backgroundImage:
312	              "linear-gradient(rgba(255,255,255,0.035) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.035) 1px, transparent 1px)",
313	            backgroundSize: "40px 40px",
314	          }}
315	          aria-hidden
316	        />
317	        <div
318	          className="pointer-events-none absolute -inset-24 opacity-70"
319	          style={{ background: `radial-gradient(40% 40% at 85% 0%, ${game.accent}30, transparent 70%)` }}
320	          aria-hidden
321	        />
322	
323	        {/* deck header */}
324	        <div className="relative flex items-center gap-3 border-b border-white/[0.07] bg-white/[0.02] px-5 py-3">
325	          <GameLogo family={game.family} size={26} />
326	          <span className="text-sm font-semibold text-white">{game.worldName}</span>
327	          <span className="hidden font-mono text-[11px] text-slate-500 sm:inline">{game.region}</span>
328	          <span className="ml-auto inline-flex items-center gap-1.5 rounded-full bg-emerald-500/12 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wide text-emerald-300">
329	            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
330	            live
331	          </span>
332	        </div>
333	
334	        <div className="relative grid gap-4 p-4 lg:grid-cols-5 lg:p-5">
335	          {/* deploy terminal — HUD framed, types boot sequence */}
336	          <div className="lg:col-span-3">
337	            <div className="relative h-full overflow-hidden rounded-2xl border border-white/10 bg-black/55 p-4 pt-5 font-mono text-[12px] leading-relaxed">
338	              {/* scan line */}
339	              {!reduced && (
340	                <div
341	                  className="pv-scan pointer-events-none absolute inset-x-0 top-0 h-16"
342	                  style={{ background: `linear-gradient(to bottom, ${game.accent}00, ${game.accent}1f, ${game.accent}00)` }}
343	                  aria-hidden
344	                />
345	              )}
346	              {/* corner brackets */}
347	              {["left-2.5 top-2.5 border-l-2 border-t-2", "right-2.5 top-2.5 border-r-2 border-t-2", "left-2.5 bottom-2.5 border-l-2 border-b-2", "right-2.5 bottom-2.5 border-r-2 border-b-2"].map(
348	                (pos) => (
349	                  <span key={pos} className={`absolute h-5 w-5 rounded-[3px] ${pos}`} style={{ borderColor: `${game.accent}aa` }} aria-hidden />
350	                ),
351	              )}
352	              <div className="mb-3 flex items-center gap-1.5">
353	                <span className="h-2.5 w-2.5 rounded-full bg-red-500/70" />
354	                <span className="h-2.5 w-2.5 rounded-full bg-amber-400/70" />
355	                <span className="h-2.5 w-2.5 rounded-full bg-emerald-400/70" />
356	                <span className="ml-2 text-[10px] uppercase tracking-wider text-slate-500">deploy · {game.name.toLowerCase()}</span>
357	              </div>
358	              <div className="relative">
359	                {done.map((l, i) => {
360	                  const ok = l.startsWith("✓");
361	                  return (
362	                    <div key={i} className={ok ? "font-semibold" : "text-slate-400"} style={ok ? { color: game.accent } : undefined}>
363	                      {l}
364	                    </div>
365	                  );
366	                })}
367	                {caret < game.boot.length && (
368	                  <div className="text-slate-300">
369	                    {current}
370	                    <span className="ml-0.5 inline-block h-3.5 w-1.5 translate-y-[2px] bg-slate-300 motion-safe:animate-blink" />
371	                  </div>
372	                )}
373	              </div>
374	            </div>
375	          </div>
376	
377	          {/* telemetry gauges rail */}
378	          <div className="flex flex-col gap-4 lg:col-span-2">
379	            <div className="relative rounded-2xl border border-white/[0.07] bg-white/[0.02] p-4">
380	              <p className="mb-4 text-[11px] font-semibold uppercase tracking-wider text-slate-500">Live telemetry</p>
381	              <div className="space-y-4">
382	                <Gauge label="Players" value={players} suffix={`/${totalSlots}`} pct={(players / totalSlots) * 100} accent={game.accent} active={seen} reduced={reduced} delay={80} />
383	                <Gauge label="CPU" value={cpu} suffix="%" pct={cpu} accent={game.accent} active={seen} reduced={reduced} delay={160} />
384	                <Gauge label="Memory" value={ram} suffix="%" pct={ram} accent={game.accent} active={seen} reduced={reduced} delay={240} />
385	                <Gauge label="TPS" value="20.0" pct={100} accent={game.accent} active={seen} reduced={reduced} delay={320} />
386	              </div>
387	            </div>
388	            <div className="flex items-center justify-between rounded-2xl border border-white/[0.07] bg-white/[0.02] px-4 py-3 text-[11px] text-slate-400">
389	              <span className="font-mono">uptime 4d 06h</span>
390	              <span className="inline-flex items-center gap-1.5 text-emerald-300">
391	                <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" /> healthy
392	              </span>
393	            </div>
394	          </div>
395	        </div>
396	      </div>
397	    </div>
398	  );
399	}
400	
401	/* ── numbered reason row on the scroll spine (from Editorial) ─────────────── */
402	function ReasonRow({ game, r, delay }: { game: PreviewGame; r: PreviewGame["reasons"][number]; delay: number }) {
403	  const { ref, seen } = useInViewOnce<HTMLLIElement>();
404	  return (
405	    <li
406	      ref={ref}
407	      className={`relative transition-all duration-700 ease-out ${seen ? "translate-y-0 opacity-100" : "translate-y-4 opacity-0"}`}
408	      style={{ transitionDelay: `${delay}ms` }}
409	    >
410	      <span
411	        className="absolute -left-[26px] top-1.5 h-3 w-3 rounded-full ring-4 ring-navy-950"
412	        style={{ background: game.accent }}
413	        aria-hidden
414	      />
415	      <div className="flex items-baseline gap-4">
416	        <span className="font-mono text-3xl font-bold tabular-nums" style={{ color: game.accent }}>
417	          {r.n}
418	        </span>
419	        <div>
420	          <h3 className="flex items-center gap-2.5 text-xl font-semibold text-white">
421	            <span style={{ color: game.accent }} className="opacity-90">
422	              <ReasonIcon icon={r.icon} size={18} />
423	            </span>
424	            {r.title}
425	          </h3>
426	          <p className="mt-2 max-w-lg text-[15px] leading-relaxed text-slate-400">{r.body}</p>
427	        </div>
428	      </div>
429	    </li>
430	  );
431	}
432	
433	/* ── plan card (from Cinematic) ───────────────────────────────────────────── */
434	function PlanCard({ game, p }: { game: PreviewGame; p: PreviewGame["plans"][number] }) {
435	  return (
436	    <div
437	      className={`relative flex flex-col rounded-2xl border p-6 backdrop-blur-md transition-all duration-200 ${
438	        p.popular
439	          ? "border-transparent bg-navy-900/80 shadow-2xl shadow-black/40"
440	          : "border-white/[0.07] bg-navy-900/50 hover:border-white/15"
441	      }`}
442	      style={p.popular ? { boxShadow: `0 0 0 1px ${game.accent}66, 0 24px 60px -24px ${game.accent}66` } : undefined}
443	    >
444	      {p.popular && (
445	        <span
446	          className="absolute -top-3 left-6 rounded-full px-3 py-1 text-[11px] font-semibold uppercase tracking-wider text-white"
447	          style={{ background: `linear-gradient(90deg, ${game.accent}, #3b82f6)` }}
448	        >
449	          Most popular
450	        </span>
451	      )}
452	      <div className="flex items-baseline justify-between">
453	        <div>
454	          <p className="text-xs font-semibold uppercase tracking-wider" style={{ color: game.accent }}>
455	            {p.tier}
456	          </p>
457	          <h3 className="mt-1 text-2xl font-bold text-white">{p.ram} RAM</h3>
458	        </div>
459	        <span className="text-xs font-medium text-slate-500">{p.meta}</span>
460	      </div>
461	      <p className="mt-4">
462	        <span className="text-4xl font-bold text-white">{p.price}</span>
463	        <span className="text-sm text-slate-500">/mo</span>
464	      </p>
465	      <p className="mt-3 text-sm leading-relaxed text-slate-400">{p.blurb}</p>
466	      <ul className="mt-5 space-y-2.5 border-t border-white/[0.06] pt-5">
467	        {p.features.map((f) => (
468	          <li key={f} className="flex items-center gap-2.5 text-sm text-slate-300">
469	            <span style={{ color: game.accent }} className="flex-none">
470	              <IconCheck size={16} />
471	            </span>
472	            {f}
473	          </li>
474	        ))}
475	      </ul>
476	      <Link
477	        href="/game-servers"
