111	/** Types out lines char-by-char once active. Returns fully-typed under reduced motion. */
112	export function useTypedLines(lines: string[], active: boolean, reduced = false) {
113	  const [done, setDone] = useState<string[]>(reduced || !active ? (active ? lines : []) : []);
114	  const [current, setCurrent] = useState("");
115	  const [caret, setCaret] = useState(reduced ? lines.length : 0);
116	  useEffect(() => {
117	    if (!active) return;
118	    if (reduced) {
119	      setDone(lines);
120	      setCaret(lines.length);
121	      return;
122	    }
123	    setDone([]);
124	    setCurrent("");
125	    setCaret(0);
126	    let li = 0;
127	    let ci = 0;
128	    let timer: ReturnType<typeof setTimeout>;
129	    const step = () => {
130	      if (li >= lines.length) return;
131	      const line = lines[li];
132	      if (ci <= line.length) {
133	        setCurrent(line.slice(0, ci));
134	        ci += 1;
135	        timer = setTimeout(step, 18 + Math.random() * 26);
136	      } else {
137	        setDone((d) => [...d, line]);
138	        setCaret(li + 1);
139	        li += 1;
140	        ci = 0;
141	        setCurrent("");
142	        timer = setTimeout(step, 340);
143	      }
144	    };
145	    timer = setTimeout(step, 500);
146	    return () => clearTimeout(timer);
147	  }, [active, reduced, lines]);
148	  return { done, current, caret };
149	}
