151	/**
152	 * Scroll-linked progress (0→1) for how far a section's top has travelled through
153	 * the viewport. Used for the editorial reason "spine". 0 under reduced motion is
154	 * fine — but we still want the spine full when the section is read, so it tracks
155	 * regardless and is just not animated by CSS.
156	 */
157	export function useScrollProgress<T extends HTMLElement = HTMLDivElement>() {
158	  const ref = useRef<T | null>(null);
159	  const [p, setP] = useState(0);
160	  useEffect(() => {
161	    const el = ref.current;
162	    if (!el) return;
163	    let raf = 0;
164	    const compute = () => {
165	      raf = 0;
166	      const r = el.getBoundingClientRect();
167	      const vh = window.innerHeight || 1;
168	      // 0 when the top hits 70% of viewport, 1 when the bottom passes 40%.
169	      const total = r.height + vh * 0.3;
170	      const travelled = vh * 0.7 - r.top;
171	      setP(Math.max(0, Math.min(1, travelled / total)));
172	    };
173	    const onScroll = () => {
174	      if (!raf) raf = requestAnimationFrame(compute);
175	    };
176	    compute();
177	    window.addEventListener("scroll", onScroll, { passive: true });
178	    window.addEventListener("resize", onScroll, { passive: true });
179	    return () => {
180	      window.removeEventListener("scroll", onScroll);
181	      window.removeEventListener("resize", onScroll);
182	      if (raf) cancelAnimationFrame(raf);
183	    };
184	  }, []);
185	  return { ref, p };
186	}
