103	          className="group flex items-center gap-2 rounded-lg border border-white/[0.06] bg-white/[0.03] px-3 py-1.5 transition-colors hover:border-white/15"
104	          aria-label={`${b.score} out of 5 on ${b.name} — ${b.count} reviews`}
105	        >
106	          <Stars color={b.star} />
107	          <span className="text-xs text-slate-400">
108	            <span className="font-semibold text-white">{b.score}</span> on{" "}
109	            {b.google ? (
