import type { Metadata } from "next";
import { GameLandingCombined } from "@/components/marketing/gamelanding/GameLandingCombined";
import { PREVIEW_GAMES } from "@/components/marketing/gamelanding/data";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { ProductOffersJsonLd, FaqJsonLd, APP_URL } from "@/components/marketing/StructuredData";

// PREVIEW ROUTE — not a live product page. Kept out of search + sitemaps.
// Flagship "greatest-hits" merge of Directions A/B/C.
export const metadata: Metadata = {
  title: "Preview · Combined game landing (Flagship)",
  description:
    "Flagship game-server landing preview: a cinematic live-ops hero, an interactive pricing configurator, a HUD deploy console, and honest social proof — deploy a managed Rust server in ~47 seconds.",
  robots: { index: false, follow: false },
  openGraph: {
    title: "Nxeon Rust Server Hosting — deploy in ~47 seconds",
    description:
      "Managed Rust hosting on a low-latency Singapore network. One-click Oxide/uMod, full FTP, DDoS protection, and a live pricing configurator that sizes a plan to your player count.",
    type: "website",
    url: `${APP_URL}/preview/game-combined`,
  },
};

